INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m19319$nota-0290$m19319$, $m19320$Exercise Physiology McArdle.pdf$m19320$, $m19321$917$m19321$, $m19322$Studies of Finnish elite track and field athletes report physician-diagnosed asthma in 17% of long-distance runners, 8% of power athletes, and 3% of nonathletic controls, while 35% of figure skaters showed a significant increase in airway resistance following skating routines.$m19322$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m19323$nota-0290$m19323$, $m19324$Exercise Physiology McArdle.pdf$m19324$, $m19325$916$m19325$, $m19326$For nearly 90% of persons with asthma and 30 to 50% of those suffering from allergic rhinitis and hay fever, physical activity provides a potent stimulus for bronchoconstriction, termed exercise-induced bronchospasm.$m19326$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m19327$nota-0290$m19327$, $m19328$Exercise Physiology McArdle.pdf$m19328$, $m19329$917$m19329$, $m19330$As the incoming breath of air moves down the respiratory tract, heat and water move away from the airway lining as the air warms and humidifies. The conditioning of inspired air ultimately cools and dries the respiratory mucosa. Drying increases mucosal lining osmolality, with accompanying mast cell degranulation. This in turn releases powerful proinflammatory mediators that trigger bronchoconstriction.$m19330$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m19331$nota-0145$m19331$, $m19332$Training and Racing with a Power Meter.pdf$m19332$, $m19333$468$m19333$, $m19334$Anaerobic threshold (AT) More correctly termed 'ventilatory threshold'; the exercise intensity at which there is a nonlinear increase in ventilation relative to metabolic rate... Although they are not mechanistically related (i.e., not related as cause and effect), 'anaerobic' or ventilatory threshold is often used to estimate lactate threshold.$m19334$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m19335$nota-0145$m19335$, $m19336$Training and Racing with a Power Meter.pdf$m19336$, $m19337$470$m19337$, $m19338$Lactate Threshold (LT) The exercise intensity at which the release of lactate into the blood first begins to exceed its rate of removal... From the perspective of most athletes and coaches, LT is a relatively low intensity, approximately corresponding to the transition between Levels 2 and 3.$m19338$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m19339$nota-0145$m19339$, $m19340$Training and Racing with a Power Meter.pdf$m19340$, $m19341$471$m19341$, $m19342$Maximal Lactate Steady State (MLSS) The highest exercise intensity at which blood lactate levels remain essentially constant over time. MLSS is comparable to functional threshold power and is closer to what most coaches and athletes mistakenly call 'LT.'$m19342$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m19343$nota-0145$m19343$, $m19344$Training and Racing with a Power Meter.pdf$m19344$, $m19345$472$m19345$, $m19346$Onset of Blood Lactate (OBLA) The exercise intensity corresponding to a blood lactate concentration of 4 millimoles per liter. An individual's OBLA is generally close to, but may be significantly higher or lower than, his or her MLSS or FTP.$m19346$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m19347$nota-0145$m19347$, $m19348$nota-0021$m19348$, $m19349$complementa$m19349$, $m19350$esclarece que a FTP (nota-0021) é conceitualmente mais próxima do MLSS do que do que costuma ser chamado coloquialmente de 'limiar de lactato' (LT)$m19350$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m19351$nota-0166$m19351$, $m19352$Manual treinamento.pdf$m19352$, $m19353$74$m19353$, $m19354$Em pH fisiológico... praticamente não existe ácido lático circulando no organismo. O que encontramos é lactato.$m19354$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m19355$nota-0166$m19355$, $m19356$Manual treinamento.pdf$m19356$, $m19357$75$m19357$, $m19358$Mesmo em repouso, o organismo produz lactato continuamente. Durante exercícios leves, moderados e intensos, a produção permanece ativa. O que muda é o equilíbrio entre produção e remoção... O aumento do lactato não significa ausência de oxigênio. Significa aumento da taxa glicolítica.$m19358$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m19359$nota-0167$m19359$, $m19360$Manual treinamento.pdf$m19360$, $m19361$76$m19361$, $m19362$o fisiologista George Brooks propôs uma teoria... Lactate Shuttle. Segundo esse modelo, o lactato funciona como um sistema de transporte de energia entre diferentes tecidos... pode ser transportado para fibras musculares oxidativas, músculo cardíaco, fígado, cérebro, rins. Nesses tecidos, o lactato pode ser convertido novamente em piruvato e utilizado para produzir ATP. Isso significa que o lactato é um combustível. Não um resíduo.$m19362$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m19363$nota-0167$m19363$, $m19364$nota-0166$m19364$, $m19365$complementa$m19365$, $m19366$reforça a reformulação do lactato de 'produto residual' para 'combustível dinâmico', complementando a correção terminológica/conceitual da nota-0166$m19366$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m19367$nota-0168$m19367$, $m19368$Manual treinamento.pdf$m19368$, $m19369$77$m19369$, $m19370$'O lactato causa fadiga.' Evidência científica: Não. O lactato está associado ao aumento da intensidade do exercício, mas não é considerado o principal causador da fadiga muscular... diversos estudos sugerem que o próprio lactato pode exercer efeitos protetores sobre a função muscular. A fadiga resulta da interação de inúmeros mecanismos: alterações iônicas, redução da disponibilidade energética, acúmulo de fosfato inorgânico, alterações neurais, fatores centrais, fatores periféricos.$m19370$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m19371$nota-0168$m19371$, $m19372$nota-0167$m19372$, $m19373$complementa$m19373$, $m19374$reforça a reinterpretação moderna do lactato (Lactate Shuttle, nota-0167) desconstruindo especificamente o mito de que ele causaria fadiga$m19374$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m19375$nota-0169$m19375$, $m19376$Manual treinamento.pdf$m19376$, $m19377$78$m19377$, $m19378$É importante observar que atletas de elite continuam produzindo grandes quantidades de lactato. A diferença está na capacidade de utilizá-lo. Por isso, o objetivo do treinamento não consiste em 'produzir menos lactato', mas em melhorar sua utilização.$m19378$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m19379$nota-0169$m19379$, $m19380$nota-0167$m19380$, $m19381$complementa$m19381$, $m19382$detalha a consequência prática do modelo Lactate Shuttle: o treino não reduz a produção, aumenta a capacidade de reutilização (nota-0167)$m19382$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m19383$nota-0170$m19383$, $m19384$Manual treinamento.pdf$m19384$, $m19385$82$m19385$, $m19386$É importante compreender que eles não representam interruptores biológicos. O organismo não muda completamente seu funcionamento ao ultrapassar determinado watt ou determinada frequência cardíaca. Na realidade, os limiares representam regiões de transição entre diferentes estados fisiológicos.$m19386$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m19387$nota-0170$m19387$, $m19388$nota-0047$m19388$, $m19389$complementa$m19389$, $m19390$reforça, com base fisiológica explícita, a mesma ideia já registrada na nota-0047 do Livro 1 (níveis de treino são um contínuo sem fronteira rígida)$m19390$)
